var response = app.alert("Choose Color:\n\n[Yes] = Magenta (1,0,1)\n[No] = Yellow (1,1,0)\n[Cancel] = Cyan (0,1,1)", 2, 3);

var color;
if (response == 4) {       // Yes clicked
  color = [1, 0, 1];
} else if (response == 3) { // No clicked
  color = [1, 1, 0];
} else if (response == 2) { // Cancel clicked
  color = [0, 1, 1];
}

if (response !== 0) {
    selectedAnnots[0].setProps({
        fillColor: ["RGB"].concat(color),
        opacity: 0.30499267578125,
        width: 0
});
}
